export default function retryWithDelay(fn, retries = 3, delayMs = 100) {
  return new Promise((resolve, reject) => {
    const attempt = (attemptsLeft) => {
      Promise.resolve()
        .then(() => fn())
        .then(resolve)
        .catch((error) => {
          if (attemptsLeft <= 0) {
            reject(error);
            return;
          }
          setTimeout(() => attempt(attemptsLeft - 1), delayMs);
        });
    };
    attempt(retries);
  });
}

